mapper.select:
SELECT sbd.id, sbd.code, sbd.source_id, sbd.dict_platform AS dictPlatform, sbd.shop_id, sbd.shop_name AS shopName, sbd.so_code AS soCode, sbd.status, sbd.picking_type AS pickingType, sbd.logistics_channel_id, sbd.logistics_channel_name AS logisticsChannelName, sbd.is_print_picking AS isPrintPicking, sbd.is_inspection AS isInspection, sbd.is_weigh AS isWeigh, sbdd.sku_id, sbdd.sku_no AS skuNo, sbdd.delivery_qty AS deliveryQty, sbdd.warehouse_id, sbdd.warehouse_name AS warehouseName, sbdd.warehouse_location AS warehouseLocation, sbd.create_time AS createTime, sbd.delivery_time AS deliveryTime FROM so_b2c_delivery sbd LEFT JOIN so_b2c_delivery_detail sbdd ON sbd.id = sbdd.main_id AND sbd.is_deleted = FALSE WHERE sbdd.is_deleted = FALSE
AND sbd.status = #{params.tabFlag}
AND sbd.code ILIKE concat('%',#{params.code}::text,'%')
AND sbd.dict_platform IN
#{dictPlatform}
AND sbd.shop_id IN
#{shopId}
AND sbd.so_code ILIKE concat('%',#{params.soCode}::text,'%')
and sbd.status in
#{status}
and sbd.picking_type in
#{pickingType}
and sbd.logistics_channel_id in
#{logisticsChannelId}
AND sbd.is_print_picking = #{params.isPrintPicking}
AND sbd.is_inspection = #{params.isInspection}
AND sbd.is_weigh = #{params.isWeigh}
AND sbdd.sku_no in
#{skuNo}
AND sbdd.warehouse_id in
#{warehouseId}
AND sbd.create_time >= #{params.createTimeList[0]} AND sbd.create_time < (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' )
AND sbd.delivery_time >= #{params.deliveryTimeList[0]} AND sbd.delivery_time < (#{params.deliveryTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' )
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sbd.create_time desc
